"""Build the Persian R&D journal from saved experiment outputs; no cloud writes."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
blocks=[]
def p(text): blocks.append({'type':'p','text':text})
def h(text,level=1): blocks.append({'type':'h','level':level,'text':text})
def table(title,headers,rows): blocks.append({'type':'table','title':title,'headers':headers,'rows':rows})
def load(name): return json.loads((ROOT/'results'/name).read_text())
def pct(n,d=3): return f'{float(n):+.{d}f}%'
def number(n,d=3): return f'{float(n):.{d}f}%'
def money(n): return f'{float(n):+,.0f}'
